for (const locale of Object.keys(shortLabels) as LocaleCode[]) {
  shortKeys.forEach((key,i) => { messages[locale][`sets.${key}`] = shortLabels[locale]![i]; });
  stageKeys.forEach((key,i) => { messages[locale][`sets.stage.${key}`] = stageLabels[locale]![i]; });
  ["queued","succeeded","failed"].forEach((key,i) => { messages[locale][`sets.run.${key}`] = runLabels[locale]![i]; });
  messages[locale]["sets.run.running"] = messages[locale]["sets.stage.generating"];
  messages[locale]["sets.run.cancelled"] = messages[locale]["sets.stage.stopped"];
  slotLabels[locale]!.forEach((value,i) => { messages[locale][`sets.slot${i}`] = value; });
  longKeys.forEach((key,i) => { messages[locale][`sets.${key}`] = longLabels[locale]![i]; });
}
